  product_row jsonb;
  group_row jsonb;
  option_row jsonb;
  category_uuid uuid;
  product_uuid uuid;
  group_uuid uuid;
  product_position integer := 0;
  group_position integer;
  option_position integer;
  normalized_category text;
begin
  insert into public.categories(source_name,name,slug,position) values
    ('marmita grande','Marmita grande','marmita-grande',10),
    ('promoÇÃo','Promoções','promocoes',20),
    ('marmita pequena','Marmita pequena','marmita-pequena',30),
    ('marmita','Marmitas especiais','marmitas-especiais',40),
    ('combos de assados','Combos de assados','combos-assados',50),
    ('assados na brasa','Assados na brasa','assados-na-brasa',60),
    ('carnes no peso','Carnes por peso','carnes-por-peso',70),
    ('guaniÇÕes','Guarnições','guarnicoes',80),
    ('porÇÕes de mistura','Porções de mistura','porcoes-de-mistura',90),
    ('bebidas','Bebidas','bebidas',100),
    ('sucos','Sucos','sucos',110),
    ('sorvete','Sorvetes','sorvetes',120)
  on conflict(slug) do update set name=excluded.name,source_name=excluded.source_name,position=excluded.position;

  for product_row in select * from jsonb_array_elements(catalog) loop
    product_position := product_position + 10;
    normalized_category := case when product_row->>'category'='carne no peso m' then 'carnes no peso' else product_row->>'category' end;
    select id into category_uuid from public.categories where source_name=normalized_category;
    insert into public.products(source_id,category_id,name,slug,description,price,old_price,image_url,active,featured,stock,position,metadata)
    values(
      product_row->>'source_id',category_uuid,product_row->>'name','produto-'||(product_row->>'source_id'),
      nullif(product_row->>'description',''),nullif(product_row->>'price','')::numeric,nullif(product_row->>'old_price','')::numeric,
      product_row->>'image_url',true,normalized_category='promoÇÃo',nullif(product_row->>'stock','')::integer,product_position,
      jsonb_build_object('source_category',product_row->>'category','thumb_url',product_row->>'thumb_url','imported_at','2026-09-02')
    )
    on conflict(source_id) do update set category_id=excluded.category_id,name=excluded.name,description=excluded.description,price=excluded.price,old_price=excluded.old_price,image_url=excluded.image_url,position=excluded.position,metadata=excluded.metadata
    returning id into product_uuid;

    delete from public.option_groups where product_id=product_uuid;
    group_position := 0;
    for group_row in select * from jsonb_array_elements(coalesce(product_row->'option_groups','[]'::jsonb)) loop
      group_position := group_position + 10;
      insert into public.option_groups(product_id,source_group_id,name,min_select,max_select,required,selection_type,position)
      values(
        product_uuid,group_row->>'source_group_id',group_row->>'name',
        case when product_row->>'price' is null and
          ((upper(group_row->>'name') like '%PAGAMENTO%') or jsonb_array_length(product_row->'option_groups')=1)
          then 1 else coalesce((group_row->>'min')::integer,0) end,
        greatest(1,coalesce((group_row->>'max')::integer,1)),
        case when product_row->>'price' is null and
          ((upper(group_row->>'name') like '%PAGAMENTO%') or jsonb_array_length(product_row->'option_groups')=1)
          then true else coalesce((group_row->>'required')::boolean,false) end,
        coalesce(group_row->>'type','single'),group_position
      )
      returning id into group_uuid;
      option_position := 0;
      for option_row in select * from jsonb_array_elements(coalesce(group_row->'options','[]'::jsonb)) loop
        option_position := option_position + 10;
        insert into public.product_options(group_id,source_option_id,name,price_delta,position)
        values(group_uuid,option_row->>'source_option_id',option_row->>'name',coalesce((option_row->>'price')::numeric,0),option_position);
      end loop;
    end loop;
  end loop;
end $seed$;
